import{_ as a,o as t,c as l,a3 as r}from"./chunks/framework.BTt0kA_k.js";const s="/RelayPulse/screenshots/user/sites-empty.webp",f=JSON.parse('{"title":"安装与首次启动","description":"","frontmatter":{},"headers":[],"relativePath":"user/start/installation.md","filePath":"user/start/installation.md"}'),i={name:"user/start/installation.md"};function o(n,e,c,u,p,d){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="安装与首次启动" tabindex="-1">安装与首次启动 <a class="header-anchor" href="#安装与首次启动" aria-label="Permalink to &quot;安装与首次启动&quot;">​</a></h1><p>本手册面向 <strong>macOS 桌面端</strong>。开始前准备好模型服务商提供的服务地址、接口协议、API Key，以及至少一个可用的模型名称。</p><h2 id="下载应用" tabindex="-1">下载应用 <a class="header-anchor" href="#下载应用" aria-label="Permalink to &quot;下载应用&quot;">​</a></h2><p>前往 <a href="https://github.com/skyzfdance/RelayPulse/releases" target="_blank" rel="noreferrer">RelayPulse 发布页</a>，查看版本说明和附件。</p><p>本手册编写时，<a href="https://github.com/skyzfdance/RelayPulse/releases/tag/v3.0.1" target="_blank" rel="noreferrer">v3.0.1 发布页</a>尚未附带桌面安装包。请以发布页实际附件为准；只有源码压缩包时，普通使用者需等待安装包发布，或向项目维护者询问分发安排。</p><ul><li>发布附件中有适合你的 Mac 的安装包时，按附件说明安装。若为 <code>.dmg</code>，打开后将应用拖到“应用程序”文件夹。</li><li>若某个版本只有 GitHub 自动生成的 <code>Source code</code> 压缩包，它们是源代码，不能直接作为桌面应用安装。</li><li>若同时提供 Apple Silicon 和 Intel 安装包，在苹果菜单“关于本机”中确认芯片类型后选择对应附件。</li></ul><p>下载后先阅读该版本说明，确认是否有升级或数据迁移提示。应用首次打开遇到系统提示时，根据 macOS 显示的具体原因处理；无法判断时保留提示内容，向项目反馈。</p><h2 id="第一次打开" tabindex="-1">第一次打开 <a class="header-anchor" href="#第一次打开" aria-label="Permalink to &quot;第一次打开&quot;">​</a></h2><ol><li>打开 RelayPulse，等待启动检查完成。</li><li>新安装且没有旧数据时，会进入主窗口。“配置 → 站点管理”显示“还没有站点”。</li><li>若显示“需要迁移旧版本数据”，按<a href="./../use/data.html#升级时提示迁移旧版本数据">版本升级说明</a>操作。</li><li>完成<a href="./quick-start.html">第一次探测</a>，确认站点、模型和凭据可用。</li></ol><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/sites-empty.webp"><img src="'+s+'" alt="首次打开后的站点管理空页面，显示“还没有站点”和“添加第一个站点”"></a></p><figcaption>没有站点时的主窗口。点击“添加第一个站点”开始配置；点击图片可查看大图。</figcaption></figure><p>RelayPulse 的主窗口用于配置；状态栏图标用于打开小面板。点击小面板的“设置”可以重新打开主窗口。</p>',11)])])}const _=a(i,[["render",o]]);export{f as __pageData,_ as default};
